mapper.select:
SELECT A.BoNode , A.BoNode.ToString() AS BoNodeText , A.BoNode.GetAncestor(0).ToString() AS ParentNode , A.BoLevel , A.BoNum , A.BoCate , dbo.GetCodeNm('BoCate', A.BoCate) AS BoCateNM , A.LinqSeq , A.Subject , A.UserId , A.Content , CONVERT(VARCHAR(16), A.RegDt, 121) AS RegDate , CASE WHEN A.BoLevel = 1 THEN ( SELECT COUNT(*) FROM TB_BOARD B WHERE B.BoNode.ToString() LIKE A.BoNode.ToString() + '%' ) -1 ELSE 0 END AS CommentCnt , ( SELECT COUNT(*) FROM dbo.TB_FILES AS BM WHERE BM.CON_SEQ = A.BoNum) AS FileCnt , COUNT(*) OVER() AS BoRowCnt FROM dbo.TB_BOARD A WHERE 1 = 1
AND A.RegDt BETWEEN CAST(#{startDate} AS date) AND dateadd(day, 1 , CAST(#{endDate} AS date))
AND A.Subject LIKE #{title} + '%'
AND A.BoCate = #{boardType}
AND A.BoNode.ToString() LIKE #{ParentNode} + '%'
AND A.LinqSeq = #{LinqSeq}

mapper.update:
		{call BOARD_ADMIN_UPDATE(
            #{BoNum, mode=IN, jdbcType=INTEGER, javaType=int},
            #{BoCate, mode=IN, jdbcType=VARCHAR, javaType=string},
            #{BizCode, mode=IN, jdbcType=INTEGER, javaType=int},
            #{Subject, mode=IN, jdbcType=VARCHAR, javaType=string},
            #{Content, mode=IN, jdbcType=VARCHAR, javaType=string}
		)}
